import{products,extrasByCategory,extrasByProduct}from"./catalog.js";const key="renato-cart-v2";let initial={};try{initial=JSON.parse(localStorage.getItem(key)||"{}")}catch{}export const quantities={};for(const product of products){const qty=initial?.[product.id];if(product.price!==null&&Number.isInteger(qty)&&qty>0&&qty<=99)quantities[product.id]=qty}let savedExtras={};try{savedExtras=JSON.parse(localStorage.getItem("renato-extras-v1")||"{}")}catch{}export const selections={};for(const product of products)selections[product.id]=((extrasByProduct[product.id]??extrasByCategory[product.category])||[]).filter(extra=>Array.isArray(savedExtras?.[product.id])&&savedExtras[product.id].includes(extra.id)).map(extra=>extra.id);export function setExtra(id,extraId,selected){const product=products.find(p=>p.id===id);if(!((extrasByProduct[product?.id]??extrasByCategory[product?.category])||[]).some(e=>e.id===extraId))return;selections[id]=selected?[...new Set([...selections[id],extraId])]:selections[id].filter(e=>e!==extraId);try{localStorage.setItem("renato-extras-v1",JSON.stringify(selections))}catch{}}export const items=()=>products.filter(p=>quantities[p.id]).map(p=>{const extras=((extrasByProduct[p.id]??extrasByCategory[p.category])||[]).filter(e=>selections[p.id].includes(e.id));return{...p,extras,unitPrice:p.price+extras.reduce((sum,e)=>sum+e.price,0),quantity:quantities[p.id]}});export const count=()=>items().reduce((sum,p)=>sum+p.quantity,0);export const subtotal=()=>items().reduce((sum,p)=>sum+p.unitPrice*p.quantity,0);export function change(id,delta){if(!products.some(p=>p.id===id&&p.price!==null)||!Number.isInteger(delta))return false;const next=Math.max(0,Math.min(99,(quantities[id]||0)+delta));if(next===(quantities[id]||0))return false;if(next)quantities[id]=next;else delete quantities[id];try{localStorage.setItem(key,JSON.stringify(quantities))}catch{}return true}
